-- 0027: Add only Vibe Coding data to the live sections; keep all existing D1-managed skills.
UPDATE sections SET zh = json_set(zh, '$.vibecoding', json('["LLM 協作開發","需求拆解與垂直切片","前後端整合","迭代除錯與瀏覽器驗證","部署與資料同步"]')), en = json_set(en, '$.vibecoding', json('["LLM-assisted coding","Requirement slicing","Full-stack integration","Iterative debugging & browser review","Deployment & data sync"]')), updated_at = datetime('now') WHERE key = 'skills_matrix';
UPDATE sections SET zh = json_set(zh, '$.vibecoding', json('{"title":"Vibe Coding 設計","en":"Vibe Coding & Product Delivery","overview":"把需求拆成能執行、能驗證的小步驟，與 LLM 協作完成介面、資料流程、整合和部署；再回到實際執行環境檢查結果。","skills":[{"name":"LLM 協作開發","level":"熟悉","desc":"先描述目標、限制和完成條件，再用 LLM 協助產生或修改程式；把生成結果放回專案脈絡檢查，而不是直接照單全收。曾用於 FRC 團隊韌體除錯與個人網站、工具專案。","projects":["FRC 7645 — 官網與後台 CMS","Job Radar — 個人化求職雷達"]},{"name":"需求拆解與垂直切片","level":"熟悉","desc":"把使用流程拆成介面、資料欄位、API 與儲存等可逐段完成的工作；先讓主要路徑跑通，再補管理、篩選和錯誤處理。","projects":["南港高工校園樹木量測 PWA","Job Radar — 個人化求職雷達","TeamMatch — 黑客松找隊友平台"]},{"name":"前後端與服務整合","level":"熟悉","desc":"依專案選擇合適組合，串接 React／Vite、Next.js 或 Flask 介面與 Cloudflare Pages、D1、Firebase、Google Apps Script 等服務；資料與帳號設定不足時先確認邊界，不假裝功能已驗證。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","TeamMatch — 黑客松找隊友平台","Analog IC Studio — 類比 IC 自動調參平台"]},{"name":"迭代除錯與瀏覽器驗證","level":"熟悉","desc":"以錯誤訊息、網路請求和實際頁面定位問題；每次修改後啟動專案、重走主要操作，確認輸出與資料流。UI 截圖用來核對畫面，不當成功能測試的替代品。","projects":["Analog IC Studio — 類比 IC 自動調參平台","Virtual Office — 桌面像素辦公室","南港高工校園樹木量測 PWA"]},{"name":"自動化部署與資料同步","level":"熟悉","desc":"用 Git 管理修改，透過 GitHub Actions 或 Cloudflare Pages 發佈；需要時同步 D1、Google Sheets 等資料來源，並在正式網址核對頁面和資源。","projects":["Job Radar — 個人化求職雷達","南港高工校園樹木量測 PWA","FRC 7645 — 官網與後台 CMS"]}]}')), en = json_set(en, '$.vibecoding', json('{"title":"Vibe Coding & Product Delivery","en":"Vibe Coding & Product Delivery","overview":"Turn a request into small, runnable steps; work with an LLM on the interface, data flow, integrations, and deployment, then check the result in the running project.","skills":[{"name":"LLM-assisted coding","level":"熟悉","desc":"Describe the goal, constraints, and acceptance conditions first, then use an LLM to draft or revise code. Review the result in the project context instead of accepting generated code blindly. Used for FRC firmware debugging and personal web/tool projects.","projects":["FRC 7645 — Website & Admin CMS","Job Radar: Personalized Job Search Dashboard"]},{"name":"Requirement slicing","level":"熟悉","desc":"Break a workflow into interface, data fields, API, and storage tasks that can be built and checked one at a time. Get the main path running before adding admin, filters, and error handling.","projects":["NKHS Campus Tree Measurement PWA","Job Radar: Personalized Job Search Dashboard","TeamMatch — Hackathon Teammate Finder"]},{"name":"Full-stack integration","level":"熟悉","desc":"Choose a fitting stack and connect React/Vite, Next.js, or Flask interfaces with services such as Cloudflare Pages, D1, Firebase, and Google Apps Script. Check configuration and access boundaries instead of claiming an unverified integration works.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","TeamMatch — Hackathon Teammate Finder","Analog IC Studio — Automated Analog IC Tuning Platform"]},{"name":"Iterative debugging & browser review","level":"熟悉","desc":"Use error messages, network requests, and the running page to locate issues. After each change, launch the project and walk through its main flow. Use screenshots to review presentation, not as a substitute for functional tests.","projects":["Analog IC Studio — Automated Analog IC Tuning Platform","Virtual Office — Desktop Pixel Workspace","NKHS Campus Tree Measurement PWA"]},{"name":"Deployment & data sync","level":"熟悉","desc":"Track changes with Git, publish through GitHub Actions or Cloudflare Pages, sync sources such as D1 or Google Sheets when needed, and verify the production URL and assets.","projects":["Job Radar: Personalized Job Search Dashboard","NKHS Campus Tree Measurement PWA","FRC 7645 — Website & Admin CMS"]}]}')), updated_at = datetime('now') WHERE key = 'skills_detail';
